PROVISIONING_SQLITE_SCHEMA=r'''
CREATE TABLE provisioned_capabilities(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('module','workflow','report','branding')),code TEXT NOT NULL,config_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','pending_verification','retired')),source_interview_id TEXT NOT NULL REFERENCES onboarding_sessions(id),source_answer_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,kind,code));
CREATE TABLE verification_tasks(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,area TEXT NOT NULL,decision TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','verified','rejected','invalidated')),required_role TEXT NOT NULL,source_interview_id TEXT NOT NULL REFERENCES onboarding_sessions(id),created_at TEXT NOT NULL,verified_by TEXT,verified_at TEXT,evidence_json TEXT NOT NULL DEFAULT '{}');
'''
